let audio,master,humGain;function initAudio(){if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=$('sound').checked?.65:0;let limiter=audio.createDynamicsCompressor();limiter.threshold.value=-15;limiter.ratio.value=8;master.connect(limiter);limiter.connect(audio.destination);pigAudio=new PigAudio(audio,master,pigAudioData);breathAudio=new BreathAudio(audio,master,breathingData);humGain=audio.createGain();humGain.gain.value=0;humGain.connect(master);for(let f of [43,61]){let o=audio.createOscillator();o.frequency.value=f;o.connect(humGain);o.start();}}audio.resume().catch(e=>console.warn('Sound unavailable',e));}
